State is preserved via keepTo, an attribute set whose attribute names are the persistent storage locations. An entry is active as soon as it has something to preserve, i.e. its dirs or files are non-empty — there is no enable switch. To disable an entry whose lists are populated by other modules, override them with empty lists: keepTo."/state" = { dirs = lib.mkForce []; files = lib.mkForce [];
}; Multiple locations — and multiple users — can be configured side by side: keepTo."/state" = { # system-level data, paths are absolute dirs = [ "/var/log" ]; files = [ { file = "/etc/machine-id"; inInitrd = true; } ];
}; keepTo."/state/userdata" = { # user data of alice, paths are relative to alice's home dir username = "alice"; # hide bind-mounts from desktop environments and file managers hideMount = true; dirs = [ "Documents" "Projects" ".local/share/fish" ]; files = [ { file = ".config/foo"; method = "symlink"; } ];
};

